//! `cf` generated by `mlirformat tblgen` (`cf.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "cf.gen.rs"]
mod cf;

#[test]
fn cf_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<cf::Cf>();
    common::Fixtures::check_dialect(&opt, "cf");
}
